/* ---- MQTT 3.1.1 (OASIS) 报文编解码 ---------------------------------------------
   固定报头：1 字节控制报文类型+标志 + 1~4 字节剩余长度（7 位一组的变长编码）
   变长编码上限 268435455 字节；字符串一律是 2 字节大端长度 + UTF-8 字节
-------------------------------------------------------------------------------- */

var PACKET_TYPES = {
  1:'CONNECT', 2:'CONNACK', 3:'PUBLISH', 4:'PUBACK', 5:'PUBREC', 6:'PUBREL', 7:'PUBCOMP',
  8:'SUBSCRIBE', 9:'SUBACK', 10:'UNSUBSCRIBE', 11:'UNSUBACK', 12:'PINGREQ', 13:'PINGRESP',
  14:'DISCONNECT', 15:'AUTH'
};

var CONNACK_CODES = {
  0:{name:'Accepted', desc:'连接已接受。'},
  1:{name:'Unacceptable protocol version', desc:'服务端不支持客户端请求的 MQTT 协议级别。'},
  2:{name:'Identifier rejected', desc:'客户端标识符格式正确但被服务端拒绝（常见于长度或字符限制）。'},
  3:{name:'Server unavailable', desc:'网络连接已建立，但 MQTT 服务不可用。'},
  4:{name:'Bad user name or password', desc:'用户名或密码格式错误 / 校验失败。'},
  5:{name:'Not authorized', desc:'客户端未被授权连接。'}
};

function utf8Encode(str){
  var s = String(str==null?'':str), out = [];
  for(var i=0;i<s.length;i++){
    var c = s.charCodeAt(i);
    if(c<0x80) out.push(c);
    else if(c<0x800){ out.push(0xC0|(c>>6), 0x80|(c&0x3F)); }
    else if(c>=0xD800 && c<=0xDBFF && i+1<s.length){
      var d = s.charCodeAt(i+1);
      if(d>=0xDC00 && d<=0xDFFF){
        var cp = 0x10000 + ((c-0xD800)<<10) + (d-0xDC00);
        out.push(0xF0|(cp>>18), 0x80|((cp>>12)&0x3F), 0x80|((cp>>6)&0x3F), 0x80|(cp&0x3F));
        i++;
      } else { out.push(0xE0|(c>>12), 0x80|((c>>6)&0x3F), 0x80|(c&0x3F)); }
    }
    else { out.push(0xE0|(c>>12), 0x80|((c>>6)&0x3F), 0x80|(c&0x3F)); }
  }
  return out;
}

function utf8Decode(bytes, start, end){
  var a = bytes, i = start||0, e = (end===undefined? a.length : end), out = '';
  while(i<e){
    var b = a[i];
    if(b<0x80){ out += String.fromCharCode(b); i+=1; }
    else if((b&0xE0)===0xC0){ out += String.fromCharCode(((b&0x1F)<<6)|(a[i+1]&0x3F)); i+=2; }
    else if((b&0xF0)===0xE0){ out += String.fromCharCode(((b&0x0F)<<12)|((a[i+1]&0x3F)<<6)|(a[i+2]&0x3F)); i+=3; }
    else {
      var cp = ((b&0x07)<<18)|((a[i+1]&0x3F)<<12)|((a[i+2]&0x3F)<<6)|(a[i+3]&0x3F);
      cp -= 0x10000;
      out += String.fromCharCode(0xD800+(cp>>10), 0xDC00+(cp&0x3FF));
      i+=4;
    }
  }
  return out;
}

function encodeVarint(n){
  var v = Math.floor(Number(n)||0);
  if(v<0) throw new Error('剩余长度不能为负');
  if(v>268435455) throw new Error('剩余长度超过 MQTT 上限 268435455 字节');
  var out=[];
  do {
    var b = v % 128;
    v = Math.floor(v/128);
    if(v>0) b = b | 0x80;
    out.push(b);
  } while(v>0);
  return out;
}

function decodeVarint(bytes, offset){
  var mul=1, value=0, i=offset||0, n=0, b;
  do {
    if(i>=bytes.length) return {ok:false, error:'剩余长度字段被截断'};
    b = bytes[i++]; n++;
    value += (b & 127) * mul;
    if(n>4) return {ok:false, error:'剩余长度超过 4 字节，报文非法'};
    mul *= 128;
  } while((b & 128) !== 0);
  return {ok:true, value:value, bytes:n, next:i};
}

function encodeString(str){
  var b = utf8Encode(str);
  if(b.length>65535) throw new Error('字符串 UTF-8 长度超过 65535');
  return [(b.length>>8)&0xFF, b.length&0xFF].concat(b);
}

function readString(bytes, offset){
  if(offset+2 > bytes.length) return {ok:false, error:'字符串长度字段被截断'};
  var len = (bytes[offset]<<8) | bytes[offset+1];
  if(offset+2+len > bytes.length) return {ok:false, error:'字符串内容被截断'};
  return {ok:true, value:utf8Decode(bytes, offset+2, offset+2+len), len:len, next:offset+2+len};
}

function toBytes(arr){ return (typeof Uint8Array!=='undefined') ? new Uint8Array(arr) : arr; }

function assemble(byte1, variableAndPayload){
  return toBytes([byte1].concat(encodeVarint(variableAndPayload.length), variableAndPayload));
}

function buildConnect(o){
  var c = o||{};
  var clientId = c.clientId===undefined ? 'nano-mqtt' : String(c.clientId);
  var keepAlive = c.keepAlive===undefined ? 60 : Math.max(0, Math.min(65535, Math.floor(Number(c.keepAlive)||0)));
  var clean = c.clean===undefined ? true : !!c.clean;
  var body = encodeString('MQTT').concat([0x04]);
  var flags = 0;
  if(clean) flags |= 0x02;
  var will = c.will;
  if(will && will.topic){
    flags |= 0x04;
    flags |= ((Math.max(0,Math.min(2, Number(will.qos)||0)) & 0x03) << 3);
    if(will.retain) flags |= 0x20;
  }
  if(c.username!==undefined && c.username!==null && c.username!=='') flags |= 0x80;
  if(c.password!==undefined && c.password!==null && c.password!=='') flags |= 0x40;
  body.push(flags);
  body.push((keepAlive>>8)&0xFF, keepAlive&0xFF);
  body = body.concat(encodeString(clientId));
  if(flags & 0x04){
    body = body.concat(encodeString(will.topic));
    body = body.concat(encodeString(will.payload===undefined?'':will.payload));
  }
  if(flags & 0x80) body = body.concat(encodeString(c.username));
  if(flags & 0x40) body = body.concat(encodeString(c.password));
  return assemble(0x10, body);
}

function buildPublish(o){
  var c = o||{};
  var qos = Math.max(0, Math.min(2, Math.floor(Number(c.qos)||0)));
  var byte1 = 0x30 | (c.dup?0x08:0) | (qos<<1) | (c.retain?0x01:0);
  var body = encodeString(c.topic===undefined?'':c.topic);
  if(qos>0){
    var pid = Math.max(1, Math.min(65535, Math.floor(Number(c.packetId)||1)));
    body.push((pid>>8)&0xFF, pid&0xFF);
  }
  var payload = c.payload;
  if(payload===undefined || payload===null) payload = [];
  else if(typeof payload === 'string') payload = utf8Encode(payload);
  else payload = Array.prototype.slice.call(payload);
  return assemble(byte1, body.concat(payload));
}

function buildSubscribe(o){
  var c = o||{};
  var pid = Math.max(1, Math.min(65535, Math.floor(Number(c.packetId)||1)));
  var body = [(pid>>8)&0xFF, pid&0xFF];
  var subs = c.subscriptions||[];
  if(!subs.length) throw new Error('SUBSCRIBE 至少要带一个主题过滤器');
  subs.forEach(function(s){
    body = body.concat(encodeString(s.topic));
    body.push(Math.max(0, Math.min(2, Math.floor(Number(s.qos)||0))));
  });
  return assemble(0x82, body); // 低 4 位固定为 0010
}

function buildUnsubscribe(o){
  var c = o||{};
  var pid = Math.max(1, Math.min(65535, Math.floor(Number(c.packetId)||1)));
  var body = [(pid>>8)&0xFF, pid&0xFF];
  (c.topics||[]).forEach(function(t){ body = body.concat(encodeString(t)); });
  return assemble(0xA2, body);
}

function buildPubAck(packetId){
  var pid = Math.max(1, Math.min(65535, Math.floor(Number(packetId)||1)));
  return assemble(0x40, [(pid>>8)&0xFF, pid&0xFF]);
}
function buildPingReq(){ return toBytes([0xC0, 0x00]); }
function buildDisconnect(){ return toBytes([0xE0, 0x00]); }

function decodePacket(bytes){
  var a = bytes;
  if(!a || a.length<2) return {ok:false, error:'报文至少需要 2 字节固定报头'};
  var b1 = a[0];
  var type = b1>>4, flags = b1 & 0x0F;
  var name = PACKET_TYPES[type] || ('保留类型 '+type);
  var fields = [{off:0, len:1, label:'控制报文类型 / 标志', value:'0x'+b1.toString(16).toUpperCase().padStart(2,'0')+' → '+name+' flags='+flags.toString(2).padStart(4,'0')}];
  var rl = decodeVarint(a, 1);
  if(!rl.ok) return {ok:false, error:rl.error, type:type, typeName:name};
  fields.push({off:1, len:rl.bytes, label:'剩余长度', value:rl.value+' 字节（'+rl.bytes+' 字节变长编码）'});
  var headerLength = 1 + rl.bytes;
  var total = headerLength + rl.value;
  var res = {ok:true, type:type, typeName:name, flags:flags, remainingLength:rl.value,
             headerLength:headerLength, totalLength:total, fields:fields,
             truncated:(a.length < total), extra:(a.length > total ? a.length-total : 0)};
  var p = rl.next;
  var end = Math.min(a.length, total);

  if(type===1){ // CONNECT
    var pn = readString(a, p); if(!pn.ok) return {ok:false, error:pn.error};
    fields.push({off:p, len:2+pn.len, label:'协议名', value:pn.value});
    p = pn.next;
    if(p>=end) return res;
    res.protocolLevel = a[p];
    fields.push({off:p, len:1, label:'协议级别', value:a[p]+(a[p]===4?'（MQTT 3.1.1）':(a[p]===5?'（MQTT 5.0）':'（非常见版本）'))});
    p++;
    var cf = a[p];
    res.connectFlags = cf;
    res.clean = !!(cf & 0x02);
    res.willFlag = !!(cf & 0x04);
    res.willQos = (cf>>3)&0x03;
    res.willRetain = !!(cf & 0x20);
    res.hasPassword = !!(cf & 0x40);
    res.hasUsername = !!(cf & 0x80);
    var fl = [];
    if(res.hasUsername) fl.push('username');
    if(res.hasPassword) fl.push('password');
    if(res.willRetain) fl.push('will-retain');
    if(res.willFlag) fl.push('will(qos'+res.willQos+')');
    if(res.clean) fl.push('clean-session');
    fields.push({off:p, len:1, label:'连接标志', value:'0b'+cf.toString(2).padStart(8,'0')+(fl.length?(' → '+fl.join(', ')):'')});
    p++;
    res.keepAlive = (a[p]<<8)|a[p+1];
    fields.push({off:p, len:2, label:'保活间隔', value:res.keepAlive+' 秒'+(res.keepAlive===0?'（0 = 不启用保活）':'')});
    p+=2;
    var cid = readString(a, p); if(!cid.ok) return {ok:false, error:cid.error};
    res.clientId = cid.value;
    fields.push({off:p, len:2+cid.len, label:'客户端标识符', value:cid.value===''?'(空，要求服务端分配)':cid.value});
    p = cid.next;
    if(res.willFlag){
      var wt = readString(a, p); if(!wt.ok) return {ok:false, error:wt.error};
      res.willTopic = wt.value;
      fields.push({off:p, len:2+wt.len, label:'遗嘱主题', value:wt.value}); p = wt.next;
      var wm = readString(a, p); if(!wm.ok) return {ok:false, error:wm.error};
      res.willPayload = wm.value;
      fields.push({off:p, len:2+wm.len, label:'遗嘱消息', value:wm.value}); p = wm.next;
    }
    if(res.hasUsername){
      var un = readString(a, p); if(!un.ok) return {ok:false, error:un.error};
      res.username = un.value;
      fields.push({off:p, len:2+un.len, label:'用户名', value:un.value}); p = un.next;
    }
    if(res.hasPassword){
      var pw = readString(a, p); if(!pw.ok) return {ok:false, error:pw.error};
      res.password = pw.value;
      fields.push({off:p, len:2+pw.len, label:'密码', value:'(已隐藏 '+pw.len+' 字节)'}); p = pw.next;
    }
    return res;
  }

  if(type===2){ // CONNACK
    res.sessionPresent = !!(a[p] & 0x01);
    fields.push({off:p, len:1, label:'连接确认标志', value:res.sessionPresent?'session present = 1（服务端保留了会话）':'session present = 0'});
    res.returnCode = a[p+1];
    var rc = CONNACK_CODES[res.returnCode];
    res.returnName = rc ? rc.name : '未知返回码';
    res.returnDesc = rc ? rc.desc : '不在 MQTT 3.1.1 定义范围内。';
    fields.push({off:p+1, len:1, label:'返回码', value:res.returnCode+' '+res.returnName});
    return res;
  }

  if(type===3){ // PUBLISH
    res.dup = !!(flags & 0x08);
    res.qos = (flags>>1)&0x03;
    res.retain = !!(flags & 0x01);
    var tp = readString(a, p); if(!tp.ok) return {ok:false, error:tp.error};
    res.topic = tp.value;
    fields.push({off:p, len:2+tp.len, label:'主题名', value:tp.value}); p = tp.next;
    if(res.qos>0){
      res.packetId = (a[p]<<8)|a[p+1];
      fields.push({off:p, len:2, label:'报文标识符', value:String(res.packetId)}); p+=2;
    }
    var plLen = Math.max(0, end - p);
    res.payloadBytes = plLen;
    res.payload = utf8Decode(a, p, end);
    fields.push({off:p, len:plLen, label:'有效载荷', value:plLen? (res.payload.length>120? res.payload.slice(0,120)+'…' : res.payload) : '(空)'});
    return res;
  }

  if(type===8 || type===10){ // SUBSCRIBE / UNSUBSCRIBE
    res.packetId = (a[p]<<8)|a[p+1];
    fields.push({off:p, len:2, label:'报文标识符', value:String(res.packetId)});
    p+=2;
    res.subscriptions = [];
    while(p < end){
      var ft = readString(a, p); if(!ft.ok) return {ok:false, error:ft.error};
      if(type===8){
        var q = a[ft.next];
        res.subscriptions.push({topic:ft.value, qos:q});
        fields.push({off:p, len:2+ft.len+1, label:'订阅项', value:ft.value+'  QoS '+q});
        p = ft.next+1;
      } else {
        res.subscriptions.push({topic:ft.value});
        fields.push({off:p, len:2+ft.len, label:'退订项', value:ft.value});
        p = ft.next;
      }
    }
    return res;
  }

  if(type===9){ // SUBACK
    res.packetId = (a[p]<<8)|a[p+1];
    fields.push({off:p, len:2, label:'报文标识符', value:String(res.packetId)});
    p+=2;
    res.returnCodes = [];
    while(p<end){
      var code = a[p];
      res.returnCodes.push(code);
      fields.push({off:p, len:1, label:'订阅返回码',
        value: code===0x80 ? '0x80 失败（无权限或过滤器非法）' : ('授予 QoS '+code)});
      p++;
    }
    return res;
  }

  if(type===4||type===5||type===6||type===7||type===11){
    res.packetId = (a[p]<<8)|a[p+1];
    fields.push({off:p, len:2, label:'报文标识符', value:String(res.packetId)});
    return res;
  }

  if(type===12||type===13||type===14){
    if(rl.value!==0) fields.push({off:p, len:rl.value, label:'意外负载', value:name+' 不应携带负载'});
    return res;
  }
  return res;
}

function topicMatch(filter, topic){
  var fs = String(filter==null?'':filter), ts = String(topic==null?'':topic);
  if(fs==='' || ts==='') return false;
  var f = fs.split('/'), t = ts.split('/');
  if(t[0].charAt(0)==='$' && (f[0]==='#' || f[0]==='+')) return false; // 通配符不匹配 $ 开头的系统主题
  for(var i=0;i<f.length;i++){
    if(f[i]==='#') return i===f.length-1;
    if(i>=t.length) return false;
    if(f[i]==='+') continue;
    if(f[i]!==t[i]) return false;
  }
  return f.length===t.length;
}

function validateTopic(topic, isFilter){
  var s = String(topic==null?'':topic);
  var errors = [], warnings = [];
  if(s==='') errors.push('主题不能为空，MQTT 要求至少 1 个字符。');
  if(s.indexOf('\u0000')>=0) errors.push('主题不能包含 U+0000。');
  var blen = utf8Encode(s).length;
  if(blen>65535) errors.push('主题 UTF-8 长度 '+blen+' 字节，超过 65535 上限。');
  var levels = s.split('/');
  if(!isFilter){
    if(s.indexOf('+')>=0 || s.indexOf('#')>=0) errors.push('发布用的主题名不允许包含通配符 + 或 #。');
  } else {
    levels.forEach(function(lv, i){
      if(lv.indexOf('#')>=0){
        if(lv!=='#') errors.push('第 '+(i+1)+' 层「'+lv+'」中的 # 必须独占一层。');
        else if(i!==levels.length-1) errors.push('# 只能出现在过滤器最后一层。');
      }
      if(lv.indexOf('+')>=0 && lv!=='+') errors.push('第 '+(i+1)+' 层「'+lv+'」中的 + 必须独占一层。');
    });
  }
  if(s.charAt(0)==='$') warnings.push('以 $ 开头的主题被服务端保留（如 $SYS/），通配符订阅不会匹配到它。');
  if(s.charAt(0)==='/') warnings.push('以 / 开头会产生一个空的首层，'+(isFilter?'需要用 "/x" 而不是 "x" 才能匹配。':'订阅方必须用同样的前导斜杠。'));
  if(s.length>1 && s.charAt(s.length-1)==='/') warnings.push('以 / 结尾会产生一个空的末层，"a/" 与 "a" 是两个不同主题。');
  if(s.indexOf('//')>=0) warnings.push('出现连续斜杠，中间是一个合法但容易被误读的空层。');
  if(/\s/.test(s)) warnings.push('主题包含空白字符：合法，但排查问题时极易看漏。');
  return {ok:errors.length===0, errors:errors, warnings:warnings, levels:levels.length, bytes:blen};
}

function hex(bytes){
  var out=[];
  for(var i=0;i<bytes.length;i++) out.push(bytes[i].toString(16).toUpperCase().padStart(2,'0'));
  return out.join(' ');
}

function parseHex(text){
  var s = String(text==null?'':text).replace(/0x/gi,' ').replace(/[^0-9a-fA-F]/g,' ').trim();
  if(!s) return {ok:false, error:'没有解析到十六进制字节'};
  var toks = s.split(/\s+/), out=[];
  for(var i=0;i<toks.length;i++){
    var t = toks[i];
    if(t.length%2!==0) return {ok:false, error:'第 '+(i+1)+' 组「'+t+'」不是偶数位十六进制'};
    for(var j=0;j<t.length;j+=2) out.push(parseInt(t.substr(j,2),16));
  }
  return {ok:true, bytes:toBytes(out)};
}

function hexdump(bytes){
  var lines=[];
  for(var i=0;i<bytes.length;i+=16){
    var chunk=[], ascii='';
    for(var j=0;j<16;j++){
      if(i+j<bytes.length){
        var b=bytes[i+j];
        chunk.push(b.toString(16).toUpperCase().padStart(2,'0'));
        ascii += (b>=32 && b<127) ? String.fromCharCode(b) : '.';
      } else { chunk.push('  '); ascii += ' '; }
    }
    lines.push(i.toString(16).toUpperCase().padStart(4,'0')+'  '+chunk.join(' ')+'  |'+ascii+'|');
  }
  return lines.join('\n');
}

function lint(cfg){
  var c = cfg||{};
  var out = [];
  function add(level, msg){ out.push({level:level, msg:msg}); }
  var cid = c.clientId===undefined ? '' : String(c.clientId);
  if(cid===''){
    if(c.clean===false) add('error', 'clientId 为空时必须使用 clean session=1，否则服务端应以返回码 2 拒绝连接。');
    else add('info', 'clientId 留空表示由服务端分配；这样的会话无法在断线后被恢复。');
  } else {
    var blen = utf8Encode(cid).length;
    if(blen>65535) add('error', 'clientId 超过 65535 字节。');
    else if(blen>23) add('warn', 'clientId 长度 '+blen+' 字节：规范只要求服务端接受 1–23 字节，超长部分依赖具体实现。');
    if(!/^[0-9a-zA-Z]*$/.test(cid)) add('warn', 'clientId 含非字母数字字符：规范只要求服务端支持 [0-9a-zA-Z]，其余字符可能被拒。');
  }
  if(c.password && !c.username) add('error', 'MQTT 3.1.1 规定：没有用户名时不允许携带密码（密码标志位必须为 0）。');
  var ka = Number(c.keepAlive===undefined?60:c.keepAlive);
  if(ka===0) add('warn', '保活间隔为 0 表示关闭保活机制，服务端将不会主动检测半开连接。');
  else if(ka>65535) add('error', '保活间隔超过 65535 秒，字段只有 2 字节。');
  else if(ka>300) add('info', '保活 '+ka+'s 偏长：服务端要等 1.5 倍（'+Math.round(ka*1.5)+'s）才判定客户端离线。');
  if(c.clean===false && cid==='') add('warn', '持久会话依赖固定 clientId，随机 id + clean=false 会在服务端堆积永不消费的会话。');
  if(c.will && c.will.topic){
    var wv = validateTopic(c.will.topic, false);
    wv.errors.forEach(function(e){ add('error', '遗嘱主题：'+e); });
